#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 伴舞僵尸的“状态行为”。
    /// 作用：决定伴舞现在是“走路”还是“站着不动”。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.backupDancer_State)]
    public class BackupDancer_StateBehaviour : EnemyStateBehaviour
    {
        // 构造函数：引擎创建这个行为时调用，名字交给父类就行。
        public BackupDancer_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }

        /// <summary>
        /// 引擎每帧都会问：这个伴舞“现在应该处于什么状态”？
        /// 我们只在父类的答案上做一点修改。
        /// </summary>
        protected override int GetActiveState(Entity enemy)
        {
            // 先拿到父类算好的默认状态
            var state = base.GetActiveState(enemy);

            // 如果本来要走路，但发现自己跑到队长前面了 → 改成站住等
            if (state == STATE_WALK && BackupDancer.ShouldWaitForLeader(enemy))
            {
                state = STATE_IDLE;
            }
            return state;
        }
    }
}
